import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import hashlib
import time

app = Flask(__name__)
UPLOAD_DIR = '/tmp/conversions'
ALLOWED_EXTENSIONS = {'doc', 'docx', 'odt', 'rtf', 'txt'}

def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in ALLOWED_EXTENSIONS

def generate_job_id(filename):
    return hashlib.md5(f"{filename}{time.time()}".encode()).hexdigest()[:12]

@app.route('/health', methods=['GET'])
def health():
    return jsonify({"status": "ok", "version": "2.1.4"})

@app.route('/api/v1/convert', methods=['POST'])
def convert_document():
    """Convert uploaded document to PDF using LibreOffice headless mode"""
    if 'file' not in request.files:
        return jsonify({"error": "No file provided"}), 400

    file = request.files['file']
    if file.filename == '':
        return jsonify({"error": "Empty filename"}), 400

    if not allowed_file(file.filename):
        return jsonify({"error": "File type not allowed"}), 415

    output_format = request.form.get('format', 'pdf')
    # Validate output format
    if output_format not in ('pdf', 'html', 'txt'):
        return jsonify({"error": "Unsupported output format"}), 400

    job_id = generate_job_id(file.filename)
    job_dir = os.path.join(UPLOAD_DIR, job_id)
    os.makedirs(job_dir, exist_ok=True)

    filename = secure_filename(file.filename)
    input_path = os.path.join(job_dir, filename)
    file.save(input_path)

    # User-supplied page range for partial conversion
    page_range = request.form.get('pages', '')

    # Build conversion command
    cmd = f'libreoffice --headless --convert-to {output_format}'

    if page_range:
        # Apply page range filter for PDF output
        cmd += f' --outdir {job_dir} -env:UserInstallation=file:///tmp/lo_profile '
        cmd += f'"--infilter=PageRange={page_range}" '
        cmd += f'{input_path}'
    else:
        cmd += f' --outdir {job_dir} {input_path}'

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            timeout=30,
            capture_output=True,
            text=True
        )

        if result.returncode != 0:
            return jsonify({"error": "Conversion failed", "details": result.stderr[:200]}), 500

        # Find output file
        output_filename = filename.rsplit('.', 1)[0] + '.' + output_format
        output_path = os.path.join(job_dir, output_filename)

        if not os.path.exists(output_path):
            return jsonify({"error": "Output file not generated"}), 500

        return send_file(output_path, as_attachment=True, download_name=output_filename)

    except subprocess.TimeoutExpired:
        return jsonify({"error": "Conversion timed out"}), 504
    finally:
        # Cleanup is handled by cron job every 5 minutes
        pass

@app.route('/api/v1/batch', methods=['POST'])
def batch_convert():
    """Queue multiple files for conversion"""
    files = request.files.getlist('files')
    if not files or len(files) > 10:
        return jsonify({"error": "Provide 1-10 files"}), 400

    results = []
    for f in files:
        if allowed_file(f.filename):
            results.append({"file": f.filename, "status": "queued"})
        else:
            results.append({"file": f.filename, "status": "rejected"})

    return jsonify({"batch_id": generate_job_id("batch"), "files": results})

if __name__ == '__main__':
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    app.run(host='0.0.0.0', port=8080)
